from scipy.spatial.transform import Rotation as R
import numpy as np
r=Robot(); s=r.spec(); q=np.array(r.get_obs(cameras=['robot_wrist'],video='none').meta['proprio']['now'][3:10]);
M=np.eye(4)
for a,p,ang in zip(s['arm']['axis'],s['arm']['position_m'],q):
