for name,p,d in [('ee',s['arm']['end_effector']['position_m'],None),('cam',s['cameras']['robot_wrist']['pose']['position_m'],s['cameras']['robot_wrist']['pose'])]:
 print(name,(M@np.r_[p,1])[:3]);
 if d:
  for k in ['forward','up','right']:print(k,M[:3,:3]@d[k])
